-- Logo klien untuk Laporan bulanan ("Dash × klien"). Disimpan sebagai data URL di baris klien, jadi tidak perlu bucket penyimpanan dan tidak ada
-- kebijakan baru: yang boleh mengubah klien tetap hanya Super-admin (klien_super), dan yang boleh membaca tetap Super-admin, Arcon (DS yang dipegang),
-- dan akun klien itu sendiri (klien_sendiri).
-- Hanya PNG/JPEG/WebP, bukan SVG: SVG bisa memuat skrip. Batas panjang menjaga baris klien tetap kecil (layar mengecilkan gambar sebelum menyimpan).
alter table klien add column logo text
  check (logo is null or (length(logo) <= 200000 and logo ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/]+=*$'));

-- Logo Alfagift langsung terpasang (hanya bila klien itu sudah ada dan belum punya logo); klien lain diunggah di menu Data Klien.
update klien set logo = 'data:image/png;base64,'
  where lower(btrim(nama)) = 'alfagift' and logo is null;
